{"patch":"diff --git a/src/services/db.js b/src/services/db.js
index ed4b279..b906af8 100644
--- a/src/services/db.js
+++ b/src/services/db.js
@@ -78,10 +78,19 @@ function createExecutor(client) {
 export async function withDbClient(fn) {
   if (!pool) throw new Error('数据库未初始化');
   const client = await pool.connect();
+  let connectionError = null;
+  const rememberConnectionError = (error) => {
+    connectionError ||= error;
+  };
+  // A checked-out pg Client can emit a socket error in addition to rejecting
+  // the active query. Keep the event observed until release so a network reset
+  // cannot become an unhandled EventEmitter error or return a broken client.
+  client.on('error', rememberConnectionError);
   try {
     return await fn(createExecutor(client));
   } finally {
-    client.release();
+    client.removeListener('error', rememberConnectionError);
+    client.release(connectionError || undefined);
   }
 }

@@ -93,7 +102,20 @@ export async function transaction(fn) {
       await tx.query('COMMIT');
       return result;
     } catch (err) {
-      await tx.query('ROLLBACK');
+      try {
+        await tx.query('ROLLBACK');
+      } catch (rollbackError) {
+        if (err && typeof err === 'object' && Object.isExtensible(err)) {
+          Object.defineProperty(err, 'rollbackError', {
+            value: rollbackError,
+            configurable: true,
+            enumerable: false,
+          });
+        } else {
+          throw new AggregateError([err, rollbackError],
+            'Database transaction failed and rollback also failed', { cause: err });
+        }
+      }
       throw err;
